return {
  name: node.properties.toolName?.value || 'http_post',
  description: node.properties.toolDescription?.value || 'Send data to URL via POST',
  enabled: node.properties.enabled?.value !== false,
  schema: {
    type: 'object',
    properties: {
      url: {
        type: 'string',
        description: 'The URL to post to'
      },
      body: {
        type: 'object',
        description: 'The data to send in the request body'
      },
      headers: {
        type: 'object',
        description: 'Optional HTTP headers'
      }
    },
    required: ['url', 'body']
  },
  code: `const fetch = (await import('node-fetch')).default;
const headers = {
  'Content-Type': 'application/json',
  ...(args.headers || {})
};
const response = await fetch(args.url, {
  method: 'POST',
  headers,
  body: JSON.stringify(args.body)
});
const contentType = response.headers.get('content-type');
if (contentType && contentType.includes('application/json')) {
  return await response.json();
}
return await response.text();`
};
